from scipy.spatial import cKDTree
def icp(a,b,T=None,n=40):
 T=np.eye(4) if T is None else T.copy();tree=cKDTree(b)
 for _ in range(n):
  a1=a@T[:3,:3].T+T[:3,3];dist,ind=tree.query(a1); mask=dist<.02
  aa=a1[mask]; bb=b[ind[mask]]; ac=aa.mean(0);bc=bb.mean(0)
  u,s,v=np.linalg.svd((aa-ac).T@(bb-bc)); rot=v.T@u.T
  if np.linalg.det(rot)<0:v[-1]*=-1;rot=v.T@u.T
  tt=np.eye(4);tt[:3,:3]=rot;tt[:3,3]=bc-rot@ac;T=tt@T
 return T,np.mean(dist[mask]),mask.sum()
